START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261022161001_AddScorerLinks') THEN
    ALTER TABLE "RaceScoreEvent" ADD "ActorLabel" character varying(120);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261022161001_AddScorerLinks') THEN
    CREATE TABLE "ScorerLinks" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "CompetitionId" integer NOT NULL,
        "Label" character varying(60) NOT NULL,
        "ArenaName" character varying(120) NOT NULL,
        "TokenHash" character varying(64) NOT NULL,
        "CreatedByUserId" text NOT NULL,
        "CreatedAt" timestamp with time zone NOT NULL,
        "ExpiresAt" timestamp with time zone NOT NULL,
        "RevokedAt" timestamp with time zone,
        "LastUsedAt" timestamp with time zone,
        CONSTRAINT "PK_ScorerLinks" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_ScorerLinks_Competitions_CompetitionId" FOREIGN KEY ("CompetitionId") REFERENCES "Competitions" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261022161001_AddScorerLinks') THEN
    CREATE INDEX "IX_ScorerLinks_CompetitionId" ON "ScorerLinks" ("CompetitionId");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261022161001_AddScorerLinks') THEN
    CREATE UNIQUE INDEX "IX_ScorerLinks_TokenHash" ON "ScorerLinks" ("TokenHash");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261022161001_AddScorerLinks') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261022161001_AddScorerLinks', '10.0.8');
    END IF;
END $EF$;
COMMIT;

